class Solution {
public:
    int subarrayBitwiseORs(vector<int>& arr) {
        unordered_set<int> result;
        unordered_set<int> cur;
        for (int x : arr) {
            unordered_set<int> next_cur;
            next_cur.insert(x);
            result.insert(x);
            for (int v : cur) {
                int val = v | x;
                next_cur.insert(val);
                result.insert(val);
            }
            cur = move(next_cur);
        }
        return result.size();
    }
};
